import {localDate, previousSets, summary, snapshot, validSet, weekDays} from './domain.js';

export function suggestion(ex, sessions) {
 const sets=previousSets(sessions,ex.id), range=ex.target.match(/^(\d+)\s*[–-]\s*(\d+)/);
 if(!sets.length||!range)return null;
 const low=+range[1],high=+range[2],kg=Math.min(...sets.map(s=>+s.kg));
 const increase=sets.length>=(ex.setCount??2)&&sets.every(s=>+s.reps>=high)&&kg>0;
 return {kg:increase?Math.min(2000,Math.round((kg+2.5)*100)/100):kg,reps:increase?low:Math.min(high,Math.min(...sets.map(s=>+s.reps))+1),reason:increase?'Alle Arbeitssätze erreichten zuletzt das obere Wiederholungsziel. Vorschlag: +2,5 kg.':'Zuerst die Wiederholungen im Zielbereich steigern.',increase};
}
const homeExercises=[['squat-home','Kniebeuge','Beine'],['push-ups','Liegestütze','Brust'],['bridge-home','Glute Bridge','Gesäß'],['bird-home','Bird Dog','Rumpf'],['prone-home','Reverse Snow Angel','Rücken']].map(([id,name,muscle])=>({id,name,muscle,bodyweight:true,note:'Kontrolliert und im schmerzfreien Bewegungsumfang ausführen.',target:'8–12',setCount:2,rir:'2–3'}));
export function generatePlan(profile,catalog) {
 const ids=['front-squat','bench-press','mag-grip-mid-lat-pull','seated-leg-curl','lateral-raise'];
 const gym=ids.map(id=>catalog.find(e=>e.id===id)).filter(Boolean);
 const pool=profile.equipment==='home'?homeExercises:gym.length>=4?gym:catalog.filter(e=>!e.bodyweight).slice(0,5);
 const count=Number(profile.days),days=({1:[0],2:[0,3],3:[0,2,4],4:[0,1,3,4],5:[0,1,2,4,5]})[count];
 if(!days)throw new Error('Bitte 1 bis 5 Trainingstage wählen.');
 return {id:crypto.randomUUID(),name:`${profile.goal==='strength'?'Kraft':profile.goal==='muscle'?'Muskelaufbau':'Fitness'} · ${count} Tage`,updatedAt:new Date().toISOString(),workouts:days.map((day,i)=>({id:crypto.randomUUID(),day,letter:'ABCDE'[i],name:count>3?(i%2?'Unterkörper':'Oberkörper'):`Ganzkörper ${'ABCDE'[i]}`,exercises:pool.filter((e,j)=>count<=3||(profile.equipment==='home'?(i%2?j===0||j===2||j===3:j===1||j===3||j===4):(i%2?j===0||j===3:j!==0&&j!==3))).map(e=>({...structuredClone(e),setCount:profile.level==='new'?2:3,target:profile.goal==='strength'&&!e.bodyweight?'5–8':'8–12',rir:'2–3',restSeconds:profile.goal==='strength'?180:120}))}))};
}
export function trainingCSV(state) {
 const quote=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';
 const rows=[['Datum','Training','Übung','Satz','kg','Wiederholungen','Satznotiz','Übungsnotiz','Trainingsnotiz']];
 for(const s of state.sessions)for(const ex of s.exercises)ex.sets.forEach((v,i)=>{if(v.done&&validSet(v))rows.push([s.date,snapshot(s).name,snapshot(s).exercises.find(e=>e.id===ex.id)?.name,i+1,v.kg,v.reps,v.note,ex.note,s.note]);});
 return '\ufeff'+rows.map(r=>r.map(quote).join(';')).join('\r\n');
}
export function createCoaching(c){
 const {esc:e,openDialog:open,closeDialog:close,render,persist,toast}=c,s=c.getState;
 const btn=(action,label,attrs='')=>`<button class="secondary-button" data-action="coach-${action}" ${attrs}>${label}</button>`;
 const field=(label,name,value='',type='text',attrs='')=>`<label class="form-field">${label}<input name="${name}" value="${e(value)}" type="${type}" ${attrs}></label>`;
 const select=(label,name,values,value)=>`<label class="form-field">${label}<select name="${name}">${values.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select></label>`;
 let draft,profile;
 function setup(){const p=s().preferences.coaching||{};open(`<h2>Dein Training einrichten</h2><form id="coach-setup">${select('Dein Ziel','goal',[['fitness','Allgemeine Fitness'],['muscle','Muskelaufbau'],['strength','Kraft']],p.goal)}${select('Erfahrung','level',[['new','Einstieg'],['experienced','Erfahren']],p.level)}${select('Ausrüstung','equipment',[['gym','Fitnessstudio'],['home','Zuhause ohne Geräte']],p.equipment)}${field('Trainingstage pro Woche','days',p.days||3,'number','required min="1" max="5" step="1"')}<p>Du erhältst eine bearbeitbare Planvorschau. Trainingstage kannst du anschließend im Planeditor anpassen.</p><button class="primary-button">Planvorschau erstellen</button></form>`);}
 function entry(){return `<section class="comparison-card"><h2>${s().preferences.coaching?'Deine Trainingsziele':'Persönlicher Einstieg'}</h2><p>${s().preferences.coaching?'Ziele verfolgen und den Plan an deinen Alltag anpassen.':'Wähle Ziel, Erfahrung und Ausrüstung für deinen Planvorschlag.'}</p><div class="feature-toolbar">${btn('setup','Training einrichten')}${btn('goals','Ziele & Messwerte')}</div></section>`;}
 function tools(){return `<section class="settings-card"><h2>Training & Datenschutz</h2><div class="coach-actions">${btn('setup','Persönliche Einrichtung')}${btn('reminders','Erinnerungen')}${btn('csv','Trainingsdaten als CSV')}${btn('pdf','Bericht drucken / PDF')}${btn('sessions','Anmeldungen verwalten')}${btn('delete','Konto löschen')}</div><label><input type="checkbox" data-coach-achievements ${s().preferences.achievements!==false?'checked':''}> Meilensteine anzeigen</label></section>`;}
 function goals(){const goals=s().goals||[],measures=s().measurements||[];open(`<h2>Ziele & Messwerte</h2><div class="coach-goals">${goals.map(g=>{let current=g.current;if(g.kind==='frequency')current=s().sessions.filter(v=>weekDays(new Date()).map(localDate).includes(v.date)).length;if(g.kind==='strength')current=Math.max(0,...previousSets(s().sessions,g.exerciseId).map(v=>+v.kg));if(['weight','waist'].includes(g.kind))current=[...measures].filter(m=>m.kind===g.kind).sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt.localeCompare(a.updatedAt))[0]?.value??g.current;const reached=g.target>=g.start?current>=g.target:current<=g.target;return `<article><strong>${e(g.name)}</strong><p>${current} / ${g.target} ${g.kind==='frequency'?'Einheiten diese Woche':g.kind==='waist'?'cm':'kg'} ${reached?'✓ Ziel erreicht':''}</p>${btn('remove-goal','Entfernen',`data-id="${g.id}"`)}</article>`;}).join('')||'<p>Noch keine Ziele angelegt.</p>'}</div><form id="coach-goal"><h3>Neues Ziel</h3>${select('Art','kind',[['frequency','Einheiten pro Woche'],['strength','Kraft (Gewicht einer Übung)'],['weight','Körpergewicht'],['waist','Taillenumfang']],'frequency')}${field('Bezeichnung','name','','text','required maxlength="100"')}${select('Übung (für Kraftziel)','exerciseId',c.getExercises().map(ex=>[ex.id,e(ex.name)]),'')}${field('Ausgangswert','start',0,'number','min="0" max="2000" step="any" required')}${field('Zielwert','target','','number','min="0.1" max="2000" step="any" required')}<button class="primary-button">Ziel speichern</button></form><form id="coach-measure"><h3>Messwert erfassen</h3>${select('Messung','kind',[['weight','Körpergewicht (kg)'],['waist','Taillenumfang (cm)']],'weight')}${field('Datum','date',localDate(),'date',`required max="${localDate()}"`)}${field('Wert','value','','number','required min="0.1" max="1000" step="any"')}<button class="primary-button">Messwert speichern</button></form><h3>Messverlauf</h3>${[...measures].sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<p>${e(m.date)} · ${m.kind==='weight'?'Gewicht':'Taille'}: ${m.value} ${m.kind==='weight'?'kg':'cm'} ${btn('remove-measure','Löschen',`data-id="${m.id}"`)}</p>`).join('')||'<p>Noch keine Messungen.</p>'}`);}
 function insights(sessions){const groups=new Map();for(const session of sessions)for(const ex of session.exercises){const muscle=snapshot(session).exercises.find(v=>v.id===ex.id)?.muscle||'Sonstige';groups.set(muscle,(groups.get(muscle)||0)+ex.sets.filter(v=>v.done&&validSet(v)).length);}const total=[...groups.values()].reduce((a,b)=>a+b,0),weeks=new Set(sessions.map(v=>localDate(weekDays(new Date(v.date+'T12:00:00'))[0]))).size;return `<section class="chart-card"><h2>Muskelgruppen & Konstanz</h2><p>${weeks} Wochen mit Training im ausgewählten Zeitraum · ${total} Arbeitssätze</p>${[...groups].map(([name,n])=>`<div class="coach-bar"><span>${e(name)}</span><meter min="0" max="${Math.max(1,...groups.values())}" value="${n}">${n}</meter><strong>${n}</strong></div>`).join('')||'<p>Nach deinem ersten Training erscheint die Verteilung.</p>'}<small>Sätze werden der hinterlegten Hauptmuskelgruppe zugeordnet. Das zeigt die Verteilung, keine medizinische Balancebewertung.</small>${btn('goals','Ziele & Messwerte')}</section>${s().preferences.achievements!==false?`<section class="comparison-card"><h3>Meilensteine</h3><div class="detail-tags">${[1,10,25,50,100].map(n=>`<span>${s().sessions.length>=n?'✓':'○'} ${n} Trainings</span>`).join('')}</div></section>`:''}`;}
 function suggestionView(ex){const v=suggestion(ex,s().sessions);return v?`<div class="coach-suggestion"><span>Vorschlag: <strong>${v.kg} kg × ${v.reps}</strong><small>${e(v.reason)} Bei sicherer Technik und passender Tagesform übernehmen.</small></span>${btn('suggest','Übernehmen',`data-id="${ex.id}"`)}</div>`:'';}
 function notes(){return `<section class="comparison-card"><h3>Deine Einheit</h3><label>Trainingsnotiz<textarea maxlength="3000" data-coach-session-note placeholder="Technik, Energie, Beschwerden …">${e(s().active.note||'')}</textarea></label></section>`;}
 function workoutTools(ex,idx){return `<div class="feature-toolbar">${idx?btn('move','Nach oben',`data-id="${ex.id}"`):''}${btn('replace','Übung ersetzen',`data-id="${ex.id}"`)}</div>`;}
 function reminders(){const p=s().preferences.reminders||{};open(`<h2>Erinnerungen</h2><p>Hinweise erscheinen zur gewählten Ortszeit, während die App geöffnet ist. Bei geschlossener App sind noch keine Push-Erinnerungen eingerichtet.</p><form id="coach-reminders"><label><input type="checkbox" name="enabled" ${p.enabled?'checked':''}> Erinnerungen aktiv</label>${field('Training','training',p.training||'18:00','time','required')}${field('Gewohnheiten','habits',p.habits||'20:00','time','required')}<button class="primary-button">Speichern</button></form>${btn('permission','Browser-Mitteilungen erlauben')}<p>Browser-Status: ${e(typeof Notification==='undefined'?'nicht unterstützt':Notification.permission==='granted'?'erlaubt':Notification.permission==='denied'?'blockiert':'noch nicht erlaubt')}</p>`);}
 const sent=new Set();
 async function tick(){if(!c.isAuthenticated()||!s().preferences.reminders?.enabled)return;const date=localDate(),time=new Date().toTimeString().slice(0,5),p=s().preferences.reminders;for(const type of ['training','habits']){const key=c.accountId()+date+type;if(time!==p[type]||sent.has(key))continue;const due=type==='training'?c.workoutForDate(new Date())&&!s().sessions.some(v=>v.date===date):(s().habits||[]).some(h=>!h.archived&&h.createdDate<=date&&h.days.includes((new Date().getDay()+6)%7)&&!(s().habitEntries||[]).some(v=>v.habitId===h.id&&v.date===date&&v.value>=(h.tracking==='boolean'?1:h.target)));if(!due)continue;sent.add(key);const message=type==='training'?'Dein Training ist heute eingeplant.':'Du hast heute noch offene Gewohnheiten.';toast(message);if(typeof Notification!=='undefined'&&Notification.permission==='granted'){try{const reg=await navigator.serviceWorker.getRegistration();await reg?.showNotification('Team Progress',{body:message,tag:key});}catch{}}}}
 async function handle(action,b){if(!action.startsWith('coach-'))return false;const id=b.dataset.id;switch(action.slice(6)){
 case 'setup':setup();break;
 case 'adopt':if(draft){s().plans.push(draft);s().activePlanId=draft.id;s().preferences.coaching=profile;s().prefsUpdatedAt=new Date().toISOString();persist();draft=null;close();render();toast('Dein Plan ist aktiv und kann unter Mein Plan bearbeitet werden.');}break;
 case 'goals':goals();break;
 case 'remove-goal':case 'remove-measure':{const key=action==='coach-remove-goal'?'goals':'measurements';s()[key]=s()[key].filter(v=>v.id!==id);s().deleted[id]=new Date().toISOString();persist();goals();break;}
 case 'suggest':{const ex=s().active?.exercises.find(v=>v.id===id),source=s().active?.workout.exercises.find(v=>v.id===id),v=source&&suggestion(source,s().sessions);if(ex&&v){ex.sets.forEach(set=>{if(!set.done){set.kg=v.kg;set.reps=v.reps;}});persist();render();}break;}
 case 'move':{const a=s().active;if(!a)break;const i=a.exercises.findIndex(v=>v.id===id);if(i>0){[a.exercises[i-1],a.exercises[i]]=[a.exercises[i],a.exercises[i-1]];a.workout.exercises=a.exercises.map(v=>a.workout.exercises.find(x=>x.id===v.id));persist();render();}break;}
 case 'replace':{const a=s().active,ex=a?.exercises.find(v=>v.id===id);if(!ex)break;if(ex.sets.some(v=>v.done)){toast('Eine Übung mit abgeschlossenen Sätzen bleibt erhalten.');break;}open(`<h2>Übung ersetzen</h2><p>Offene Eingaben dieser Übung werden ersetzt. Dein Trainingsplan bleibt erhalten.</p><form id="coach-replace" data-id="${id}">${select('Ersatzübung','exerciseId',c.getExercises().filter(v=>!a.exercises.some(x=>x.id===v.id)).map(v=>[v.id,e(v.name)]),'')}<button class="primary-button">Ersetzen</button></form>`);break;}
 case 'csv':c.download('training.csv',trainingCSV(s()),'text/csv;charset=utf-8');break;
 case 'pdf':{const report=document.createElement('section');report.id='print-report';report.innerHTML=`<h1>Team Progress · Trainingsbericht</h1><p>${e(s().preferences.name)} · ${localDate()}</p>${s().sessions.map(v=>`<article><h2>${e(v.date)} · ${e(snapshot(v).name)}</h2><p>${summary(v).sets} Sätze · ${summary(v).volume} kg Volumen</p><p>${e(v.note||'')}</p>${v.exercises.map(ex=>`<p>${e(snapshot(v).exercises.find(x=>x.id===ex.id)?.name)}: ${ex.sets.filter(x=>x.done).map(x=>`${x.kg} kg × ${x.reps}`).join(', ')}</p>`).join('')}</article>`).join('')||'<p>Noch keine Trainings.</p>'}`;document.querySelector('#print-report')?.remove();document.body.append(report);window.print();break;}
 case 'reminders':reminders();break;
 case 'permission':try{if(typeof Notification==='undefined')throw Error('Dieser Browser unterstützt keine Mitteilungen.');await Notification.requestPermission();reminders();}catch(err){toast(err.message);}break;
 case 'sessions':open(`<h2>Anmeldungen verwalten</h2><p>Aktuelles Konto: ${e(c.email())}</p><p>Du kannst alle anderen Geräte abmelden. Bereits ausgestellte Zugriffstoken können bis zu ihrem Ablauf gültig bleiben.</p>${btn('revoke','Andere Geräte abmelden')}<p>Dieses Gerät meldest du in den Kontoeinstellungen ab.</p>`);break;
 case 'revoke':try{await c.revoke();toast('Andere Sitzungen wurden abgemeldet.');close();}catch(err){toast(err.message);}break;
 case 'delete':open(`<h2>Konto endgültig löschen?</h2><p>Dein Konto und alle gespeicherten Trainings und Gewohnheiten werden unwiderruflich gelöscht. Exportiere vorher bei Bedarf deine Daten in den Einstellungen.</p><form id="coach-delete">${field('Zum Bestätigen LÖSCHEN eingeben','confirmation','','text','required pattern="LÖSCHEN"')}<button class="primary-button danger">Konto endgültig löschen</button></form>`);break;
 }return true;}
 async function submit(event){const form=event.target;if(!form.id.startsWith('coach-')||!c.isAuthenticated())return;event.preventDefault();const data=Object.fromEntries(new FormData(form)),stamp=new Date().toISOString();try{
 if(form.id==='coach-setup'){profile={...data,days:+data.days};draft=generatePlan(profile,c.getExercises());open(`<h2>Deine Planvorschau</h2><p>${e(draft.name)} · ${profile.equipment==='home'?'Ohne Geräte':'Fitnessstudio'} · ${profile.level==='new'?'Einstieg':'Erfahren'}</p>${draft.workouts.map(w=>`<h3>${['Mo','Di','Mi','Do','Fr','Sa','So'][w.day]} · ${e(w.name)}</h3><ul>${w.exercises.map(ex=>`<li>${e(ex.name)} · ${ex.setCount} × ${ex.target}</li>`).join('')}</ul>`).join('')}<p>Deine bisherigen Pläne bleiben in der Planbibliothek.</p>${btn('adopt','Als aktiven Plan übernehmen')}${btn('setup','Angaben ändern')}`);return;}
 if(form.id==='coach-goal'){(s().goals||=[]).push({id:crypto.randomUUID(),...data,start:+data.start,current:+data.start,target:+data.target,updatedAt:stamp});persist();goals();return;}
 if(form.id==='coach-measure'){(s().measurements||=[]).push({id:crypto.randomUUID(),...data,value:+data.value,updatedAt:stamp});persist();goals();return;}
 if(form.id==='coach-replace'){const a=s().active,index=a.exercises.findIndex(v=>v.id===form.dataset.id),ex=c.getExercises().find(v=>v.id===data.exerciseId);if(index<0||!ex||a.exercises[index].sets.some(v=>v.done))throw Error('Übung kann nicht ersetzt werden.');a.workout.exercises[index]=structuredClone(ex);a.exercises[index]={id:ex.id,note:'',sets:Array.from({length:ex.setCount??2},()=>({kg:ex.bodyweight?0:'',reps:'',done:false}))};persist();close();render();return;}
 if(form.id==='coach-reminders'){s().preferences.reminders={enabled:data.enabled==='on',training:data.training,habits:data.habits};s().prefsUpdatedAt=stamp;persist();close();toast('Erinnerungen gespeichert.');return;}
 if(form.id==='coach-delete'){if(data.confirmation!=='LÖSCHEN')return;form.querySelector('button').disabled=true;await c.deleteAccount();}
 }catch(err){toast(err.message);if(form.isConnected)form.querySelector('button').disabled=false;}}
 document.addEventListener('submit',submit);
 document.addEventListener('change',event=>{if(!c.isAuthenticated())return;const el=event.target;if(el.matches('[data-coach-achievements]')){s().preferences.achievements=el.checked;s().prefsUpdatedAt=new Date().toISOString();persist();}});
 document.addEventListener('input',event=>{if(!c.isAuthenticated()||!s().active)return;const el=event.target;if(el.matches('[data-coach-session-note]')){s().active.note=el.value;persist();}if(el.dataset.coachSet){const ex=s().active.exercises.find(v=>v.id===el.dataset.coachSet);if(ex?.sets[+el.dataset.index]){ex.sets[+el.dataset.index].note=el.value;persist();}}});
 setInterval(tick,20000);
 return {entry,tools,insights,suggestionView,notes,workoutTools,handle};
}
